import{_ as t,a as r,o as a,a4 as o}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Place Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"place-order-onsite","title":"Place Order (on-site payment)","description":"Cash-on-delivery or money-transfer — the order is created immediately. Address, shipping method, and payment method must already be set on the cart, so the body is empty.","request":"POST /api/shop/checkout-orders\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 9372,\\n  \\"cartToken\\": \\"1536\\",\\n  \\"orderId\\": \\"554\\",\\n  \\"redirect\\": false,\\n  \\"redirectUrl\\": null,\\n  \\"success\\": true,\\n  \\"message\\": \\"Order placed successfully\\"\\n}\\n"},{"id":"place-order-redirect","title":"Place Order (payment gateway)","description":"Stripe / PayU / PhonePe / Razorpay / PayPal — no order is created yet; redirect the shopper to redirectUrl to complete payment.","request":"POST /api/shop/checkout-orders\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 9372,\\n  \\"cartToken\\": \\"1536\\",\\n  \\"orderId\\": null,\\n  \\"redirect\\": true,\\n  \\"redirectUrl\\": \\"https://your-domain.com/stripe/redirect\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"This payment method requires the shopper to complete payment on the gateway. Send them to redirectUrl; the order is created once the gateway confirms the payment.\\"\\n}\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Customer not authenticated","solution":"Provide valid Bearer token"},{"error":"400 Bad Request","cause":"Missing required checkout details","solution":"Ensure shipping address, method, and payment method are set"},{"error":"409 Conflict","cause":"Cart is empty","solution":"Add items to cart first"},{"error":"422 Unprocessable Entity","cause":"Inventory not available","solution":"Verify product stock"}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/place-order.md","filePath":"api/rest-api/shop/checkout/place-order.md","lastUpdated":1784902076000}'),d={name:"api/rest-api/shop/checkout/place-order.md"};function s(i,e,n,l,c,h){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="place-order" tabindex="-1">Place Order <a class="header-anchor" href="#place-order" aria-label="Permalink to &quot;Place Order&quot;">​</a></h1><p>Create an order from the shopping cart. This completes the checkout process.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/checkout-orders</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>The address, shipping method, and payment method are set on the cart in the preceding checkout steps, so place-order takes an <strong>empty body</strong>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>The cart id the order was placed from (not the order id).</td></tr><tr><td><code>cartToken</code></td><td>string</td><td>The cart token.</td></tr><tr><td><code>orderId</code></td><td>string</td><td>The created order id — <strong>only set on the on-site path</strong>; <code>null</code> when a payment redirect is required.</td></tr><tr><td><code>redirect</code></td><td>boolean</td><td><code>true</code> when the payment method needs the shopper sent to a payment page before the order exists.</td></tr><tr><td><code>redirectUrl</code></td><td>string</td><td>The payment page to open when <code>redirect</code> is <code>true</code>; <code>null</code> otherwise.</td></tr><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the call succeeded — order placed <strong>or</strong> redirect required. Failures return a 4xx with the reason, not <code>success: false</code>.</td></tr><tr><td><code>message</code></td><td>string</td><td>Human-readable result — &quot;order placed&quot;, or an explanation to redirect the shopper to complete payment.</td></tr></tbody></table><h3 id="two-outcomes-—-branch-on-redirect" tabindex="-1">Two outcomes — branch on <code>redirect</code> <a class="header-anchor" href="#two-outcomes-—-branch-on-redirect" aria-label="Permalink to &quot;Two outcomes — branch on `redirect`&quot;">​</a></h3><ul><li><strong><code>redirect: false</code></strong> (cash-on-delivery, money-transfer) — the order exists; read <code>orderId</code>.</li><li><strong><code>redirect: true</code></strong> (stripe, payu, phonepe, razorpay, paypal) — <strong>no order yet</strong>. <code>orderId</code> is <code>null</code>; send the shopper to <code>redirectUrl</code> to pay. The order is created when the gateway returns to your success URL. <code>message</code> explains this.</li></ul><p>On a genuine failure (empty cart, missing address/shipping/payment, suspended account, minimum-order not met) the endpoint returns a <strong>4xx</strong> with the exact reason in the error body — it does not return <code>success: false</code>.</p><h2 id="order-status-values" tabindex="-1">Order Status Values <a class="header-anchor" href="#order-status-values" aria-label="Permalink to &quot;Order Status Values&quot;">​</a></h2><ul><li><code>pending</code> - Awaiting payment confirmation</li><li><code>processing</code> - Payment confirmed, preparing shipment</li><li><code>shipped</code> - Order shipped</li><li><code>delivered</code> - Order delivered</li><li><code>canceled</code> - Order canceled</li><li><code>failed</code> - Payment failed</li></ul><h2 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h2><p>All of these must be completed before placing order:</p><ol><li>Cart must have items</li><li>Shipping address must be set</li><li>Shipping method must be selected</li><li>Billing address must be set</li><li>Payment method must be selected</li><li>All items in stock</li></ol><h2 id="after-order-placement" tabindex="-1">After Order Placement <a class="header-anchor" href="#after-order-placement" aria-label="Permalink to &quot;After Order Placement&quot;">​</a></h2><ul><li>Cart is automatically cleared</li><li>Customer receives confirmation email</li><li>Order status can be tracked</li><li>Invoice becomes available</li><li>Payment processing may redirect customer</li></ul><h2 id="validation-rules" tabindex="-1">Validation Rules <a class="header-anchor" href="#validation-rules" aria-label="Permalink to &quot;Validation Rules&quot;">​</a></h2><ul><li>Cart cannot be empty</li><li>All addresses must be complete</li><li>Inventory must be available for all items</li><li>Shipping method must match location</li><li>Payment method must be valid</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li>Complete customer checkout</li><li>Create order for in-store pickup</li><li>Process cash on delivery</li><li>Execute payment gateway transaction</li><li>Generate order confirmation and invoice</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a></li><li><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a></li><li><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a></li><li><a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a></li><li><a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a></li><li><a href="/api/rest-api/shop/customers/get-customer-orders.html">Get Customer Orders</a></li></ul>',27)]))}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
